/**
 * tce single-game launcher entry point.
 *
 * AUTO-GENERATED by scripts/game-repo-scaffold.ts. Boots a Phaser game with
 * the shared GameSelectorScene; the catalogue is generated by the core
 * game-discovery plugin from `configs/game.json` (Gym + this
 * game). Engine imports resolve into the sibling core checkout via the
 * `@ui/*` path aliases.
 */
import Phaser from 'phaser';
import { createCardGame } from '@ui/createCardGame';
import { GameSelectorScene, REGISTRY_KEY_GAMES } from '@ui/GameSelectorScene';
import { GAMES, SCENES } from 'virtual:game-registry';

export { GAMES };

const isReplayMode =
  new URLSearchParams(window.location.search).get('mode') === 'replay';

createCardGame({
  backgroundColor: '#1a2a1a',
  scenes: [GameSelectorScene, ...SCENES],
  // AUTO = WebGL when the device provides a GL context, with an automatic
  // Canvas fallback (MS-0MV1HJ9ES009Y8GK). Phaser 4's Filter system and
  // custom GPU shaders are WebGL-only, so the launcher must not pin CANVAS.
  //
  // Container clipping is renderer-aware: `src/ContainerClip.ts` applies a
  // `GeometryMask` on Canvas and a Mask filter on WebGL, because Phaser 4
  // made `setMask` a no-op under WebGL. Core-owned mask sites (HelpPanel,
  // Overlay, SettingsPanel) are tracked in `MS-0MVTE0UP00013TNW` and are not
  // yet migrated — keep that in mind before raising the renderer's priority.
  //
  // NOTE: this file is scaffold-generated by
  // `core/scripts/game-repo-scaffold.ts` (`renderMainTs`), which still emits
  // `type: Phaser.CANVAS`. A re-scaffold reverts this line until the
  // generator is updated in the core repo.
  type: Phaser.AUTO,
  render: isReplayMode ? { preserveDrawingBuffer: true } : undefined,
  callbacks: {
    preBoot: (game: Phaser.Game) => {
      game.registry.set(REGISTRY_KEY_GAMES, GAMES);
    },
  },
  exposeOnWindow: true,
});
